def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    diff: dict[int, int] = {}
    for start, end in meetings:
        if start == end:
            continue
        diff[start] = diff.get(start, 0) + 1
        diff[end] = diff.get(end, 0) - 1
    if not diff:
        return 0
    times = sorted(diff)
    active = 0
    total = 0
    prev = times[0]
    for t in times:
        if active >= k:
            total += t - prev
        active += diff[t]
        prev = t
    return total
